import{z as d,x as s,o as n,c as B,q as o,j as r,D as e,d as i,s as E,S as l}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"文字定位与 2D grounding","description":"","frontmatter":{"title":"文字定位与 2D grounding","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/qwen-ocr-text-grounding.md","filePath":"llm/qwen-ocr-text-grounding.md","lastUpdated":1791413859000}'),A={name:"llm/qwen-ocr-text-grounding.md"};function g(p,a,m,u,c,h){const t=s("Mermaid");return n(),B("div",null,[a[2]||(a[2]=o('<h1 id="文字定位与-2d-grounding" tabindex="-1">文字定位与 2D grounding <a class="header-anchor" href="#文字定位与-2d-grounding" aria-label="Permalink to &quot;文字定位与 2D grounding&quot;">​</a></h1><div class="epigraph"><p>认出字还不够；把字所在的框或点用坐标说出来，阅读顺序、点击与核对才有几何落点。</p><footer>—— Qwen2.5-VL 技术报告；Qwen3-VL 技术报告</footer></div><p>OCR 常被理解成「图到字符串」。文档与界面场景还要求<strong>文字在哪</strong>：划出题干、把表头与列对齐、给 GUI 元素一个可点的框。Qwen2.5-VL 把检测、指向与计数做成通用 grounding，框与点用<strong>输入图的实际像素</strong>表示，并支持 JSON、XML 等多种格式。Qwen3-VL 把坐标改成归一化到 \\([0,1000]\\)，仍保留框与点两种模态，并加强计数。文字定位是 grounding 在字符、词、行、栏上的特例：目标是文本实例，不是「猫」或「按钮」这一类物体名词。本篇把 2D 坐标如何进语言、如何与 HTML 框对齐写清，不另发明检测头。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>纯转录丢失几何。双栏页面上两处都出现「合计」，没有框就无法知道哪一处属于哪一张表。Agent 要点击屏幕上的某个词，必须把语言里的指称映射到像素。传统 OCR 检测器输出框与识别结果，但与 VLM 的问答、抽取是两套系统，坐标空间还要自己对齐分辨率缩放。</p><p>VLM 若只用相对坐标（\\(0\\)–\\(1\\) 或百分比）而训练时又做动态分辨率，模型难以把「框的大小」和「物体真实尺度」联系起来。Qwen2.5-VL 因此在原生分辨率上直接用原图像素当监督。代价是：换分辨率或 letterbox 后，数字串的含义随 \\(H,W\\) 变。Qwen3-VL 改为千分位归一化，换分辨率更稳，但失去像素尺度本身。问题是任务要的是「可回投的 2D 指称」，坐标系必须在训练与推理之间写成契约。</p><p><span class="marginnote">术语翻译：grounding 就是把语言里的说法「钉」到图像上的具体位置——「钉」出来的可以是框（一个范围）或点（一个中心）。文字定位即被钉的对象是字、词、行，而不是「猫」「按钮」这类物体。</span></p><p><span class="marginnote">Qwen2.5-VL：框与点用输入图实际宽高下的数值。Qwen3-VL：坐标缩放到 \\([0,1000]\\)。写应用时先看版本，不要把一套数字当另一套用。</span></p><h3 id="文字实例与物体实例共用同一套输出通道" tabindex="-1">文字实例与物体实例共用同一套输出通道 <a class="header-anchor" href="#文字实例与物体实例共用同一套输出通道" aria-label="Permalink to &quot;文字实例与物体实例共用同一套输出通道&quot;">​</a></h3><p>没有单独的「OCR 检测头」。框是语言模型生成的数字与分隔符，与物体 grounding、GUI grounding 同一条生成路径。好处是指称可以是任意短语：「右上角红色标题」「第三行金额」。坏处是框的数值精度受解码约束，不是 NMS 后的连续回归。文字定位要在提示里写清粒度（行框还是词框），否则模型会在两种粒度间摇摆。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><h3 id="框、点、计数" tabindex="-1">框、点、计数 <a class="header-anchor" href="#框、点、计数" aria-label="Permalink to &quot;框、点、计数&quot;">​</a></h3><p>框用 \\((x_1,y_1,x_2,y_2)\\)（或报告中的等价序列）标出轴对齐矩形；点用于「指这里」与计数时的一一对应。Qwen2.5-VL 用公开与自建数据，格式合成到 XML、JSON 与自定义模板，并借助 Grounding DINO、SAM 等现成模型做拷贝粘贴增强与伪框。开放词汇检测扩展到上万类，并构造「查询里出现图中不存在的类」以抑制幻觉框。指向数据含 PixMo 等公开集与针对细节的合成点。</p><p>Qwen3-VL 的框数据从 COCO、Objects365、OpenImages、RefCOCO 等汇集，再用 Qwen2.5-VL 提候选、检测器与教师联合标框、过滤低置信。点数据同样混合 PixMo、检测/分割派生与细节合成。计数分成直接报数、依框数、依点数三种题型。文字定位共享这套几何；文档上的行框往往来自 <a href="/llm/qwen-html-document-parse">HTML 解析</a> 的 <code>data-bbox</code> 与 OCR 伪标，而不是另训一套字符检测器。</p> \\[x&#39;=\\mathrm{round}\\Big(\\frac{x}{W}\\cdot 1000\\Big),\\quad y&#39;=\\mathrm{round}\\Big(\\frac{y}{H}\\cdot 1000\\Big) \\]<p>上式概括 Qwen3-VL 的归一化（实现以报告为准）。反变换时必须用<strong>模型实际看到的</strong> \\(H,W\\)（含动态分辨率缩放后的尺寸），不能用磁盘上原图尺寸而不记录预处理。</p>',16)),(n(),r(l,null,{default:e(()=>[E(t,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20LR%0A%20%20Img%5B%22%E5%8A%A8%E6%80%81%E5%88%86%E8%BE%A8%E7%8E%87%E5%9B%BE%E5%83%8F%22%5D%20--%3E%20VLM%5B%22VLM%20%E7%94%9F%E6%88%90%22%5D%0A%20%20VLM%20--%3E%20Box%5B%22%E8%BD%B4%E5%AF%B9%E9%BD%90%E6%A1%86%22%5D%0A%20%20VLM%20--%3E%20Pt%5B%22%E7%82%B9%22%5D%0A%20%20VLM%20--%3E%20Txt%5B%22%E6%96%87%E5%AD%97%E5%86%85%E5%AE%B9%22%5D%0A%20%20Box%20--%3E%20Align%5B%22%E4%B8%8E%E5%83%8F%E7%B4%A0%E7%BD%91%E6%A0%BC%E5%AF%B9%E9%BD%90%22%5D%0A%20%20Pt%20--%3E%20Align%0A%20%20Txt%20--%3E%20Align%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=o('<p><span class="marginnote">绝对像素让模型看见尺度：同样内容的大图与小图，框的数值差一截，这是 2.5 的设计意图。3 的千分位则让「左上角」在不同分辨率上数字相近，便于后处理，但尺度要另从图像 token 数或边长推断。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><h3 id="坐标是读出来的数字串" tabindex="-1">坐标是读出来的数字串 <a class="header-anchor" href="#坐标是读出来的数字串" aria-label="Permalink to &quot;坐标是读出来的数字串&quot;">​</a></h3><p>Grounding 是条件生成：视觉 token 带着 <a href="/llm/qwen3-vl-interleaved-mrope">MRoPE</a> 的高宽几何，语言模型把查询对齐到某些视觉键，再把对齐结果读成数字串。动态分辨率下，token 网格与像素网格有固定比例（merge 后约 \\(28\\) 像素一格），坐标回归本质上是「说出所依据的那些视觉 token 在网格上的范围」。文字比自然物体更细，往往只占一两个合并 token，所以定位误差对分辨率上限更敏感：<code>max_pixels</code> 太低时，小字的框会漂到邻行。</p><p>与独立 OCR 检测器相比，VLM 框与识别是联合解码，可以出现「字对框错」或「框对字错」。联合的好处是查询可以消歧：「标题里的 Qwen」而不是页脚里的。JSON 模板把字段顺序钉死，降低数字与标签错位。训练时多种格式混用，是为了测试期提示稍变仍能吐坐标，而不是模型内部真有多个检测头。</p>',5)),(n(),r(l,null,{default:e(()=>[E(t,{id:"mermaid-60",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E6%9F%A5%E8%AF%A2%EF%BC%9A%E6%A0%87%E9%A2%98%E9%87%8C%E7%9A%84%20Qwen%22%5D%20--%3E%20A%5B%22%E6%B3%A8%E6%84%8F%E5%8A%9B%E5%AF%B9%E9%BD%90%E5%88%B0%E7%9B%B8%E5%85%B3%E8%A7%86%E8%A7%89%20token%22%5D%0A%20%20A%20--%3E%20B%5B%22%E8%AF%BB%E5%87%BA%E8%BF%99%E4%BA%9B%20token%20%E7%9A%84%E7%BD%91%E6%A0%BC%E8%8C%83%E5%9B%B4%22%5D%0A%20%20B%20--%3E%20C%5B%22%E7%BD%91%E6%A0%BC%E5%9D%90%E6%A0%87%E6%8D%A2%E7%AE%97%EF%BC%9A%E7%BA%A6%2028%20%E5%83%8F%E7%B4%A0%E4%B8%80%E6%A0%BC%22%5D%0A%20%20C%20--%3E%20D%5B%22%E7%94%9F%E6%88%90%E6%95%B0%E5%AD%97%E4%B8%B2%20x1%2C%20y1%2C%20x2%2C%20y2%22%5D%0A%20%20D%20--%3E%20E%5B%22%E6%8C%89%E7%BA%A6%E5%AE%9A%E5%9D%90%E6%A0%87%E7%B3%BB%E5%9B%9E%E6%8A%95%E5%88%B0%E5%9B%BE%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=o('<p><span class="marginnote">数字实例：一张 \\(896 \\times 896\\) 的图，\\(896 \\div 28 = 32\\)，token 网格就是 \\(32 \\times 32\\)；一个占 \\(28 \\times 28\\) 像素的字只落在一格里。所以框的精度天然一格一格地跳——<code>max_pixels</code> 压得太狠，相邻两行小字挤进同一格，框就只能在行间漂。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>生成式框没有经典检测的置信度校准，NMS 也不自然。密集文字（合同小字、密集字幕）容易漏框或合并相邻行。旋转、透视下的轴对齐框会变松，本系列另有旋转矫正节点，本篇不假装 2D 框能替代四边形。手写与印章的「字」边界主观，IoU 评测会低估可用的粗定位。</p><p>坐标系契约一旦在服务端写错——用 2.5 的像素数去解 3 的千分位，或忘记动态 resize——所有框整体缩放错误，比单字识别错误更难发现。后处理应把框画回<strong>预处理后</strong>的图做可视化验收。Agent 点击还要把框中心映射到屏幕坐标，中间若有窗口缩放，又是一层几何。不要在评测里只用识别准确率代替 grounding；文字定位应报 IoU 或点是否落在字形上。</p><p><span class="marginnote">常见误区：看到框整体偏移，先怀疑模型不行，实际上多半是坐标系没对上——把千分位输出当像素画，或者反变换时用了磁盘原图尺寸而不是预处理后的尺寸。验收时把框画在「模型实际看到的那张图」上，一眼就能分辨。</span></p><p>Qwen3-VL 另有 3D 框与空间关系数据，那是物体与场景，不是 OCR 行框。本篇的 2D grounding 停在图像平面。把 9 自由度空间框拿来当文档定位，是范畴错误。<span class="marginnote">与 HTML 的 <code>data-bbox</code> 应是同一几何契约：解析输出的框要能画回预处理后的页。两套数字各用各的原点，下游高亮会整体错位，看起来像模型不会定位，其实是后处理没对齐。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>文字定位是 2D grounding 的文本实例：模型生成框或点以及对应字符串，没有单独 OCR 检测头。</li><li>Qwen2.5-VL 用原图像素坐标以保留尺度；Qwen3-VL 用 \\([0,1000]\\) 归一化以稳分辨率，反变换必须记录预处理尺寸。</li><li>框与物体、GUI grounding 共用生成通道；粒度（词/行/块）要靠提示与数据钉死。</li><li>密集小字、旋转与错误坐标系是主要失败模式；评测要分开识别与几何。</li><li>出处：Qwen2.5-VL 技术报告（绝对坐标与多格式 grounding）；Qwen3-VL 技术报告（归一化坐标、框/点/计数）；对照独立 OCR 检测器与 LayoutLM 所用的外部框。</li></ul>',8))])}const x=d(A,[["render",g]]);export{D as __pageData,x as default};
